const cfg = {
  locationId: 'Zwz4relUXVPxx8uohnjV',
  ghlApiBaseUrl: 'https://services.leadconnectorhq.com',
  ghlApiKey: 'pit-a55a45b3-f933-4898-9cbb-7cfe74c95d28',
  recipientEmail: 'ed@livetransparent.com',
  recipientFirstName: 'Ed',
  recipientLastName: 'Cadorniga',
  watchedWorkflowIds: ['HQaHuLZbtKCSaKqE'],
};

const payload = $json || {};
const wfId = payload?.workflow?.id || payload?.workflowId || payload?.execution?.workflowId || null;
if (cfg.watchedWorkflowIds.length && wfId && !cfg.watchedWorkflowIds.includes(String(wfId))) {
  return [{ json: { ok: true, skipped: true, reason: `Workflow ${wfId} not in watch list` } }];
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}

async function apiRequest({ method, path, body }) {
  const options = {
    method,
    url: `${cfg.ghlApiBaseUrl}${path}`,
    headers: {
      Authorization: `Bearer ${cfg.ghlApiKey}`,
      Version: '2021-07-28',
      'Content-Type': 'application/json',
      Accept: 'application/json',
    },
    json: true,
    body,
  };
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    return { ok: false, status: err?.statusCode || err?.httpCode || 500, data: err?.response?.body || err?.message || err, requestBody: body };
  }
}

const workflowName = payload?.workflow?.name || payload?.workflowName || 'Unknown Workflow';
const executionId = payload?.execution?.id || payload?.executionId || 'N/A';
const errMessage = payload?.error?.message || payload?.message || JSON.stringify(payload?.error || payload).slice(0, 2000);
const errStack = payload?.error?.stack || payload?.stack || '';
const nowIso = new Date().toISOString();

const subject = `[n8n Error] ${workflowName}`;
const bodyText = [
  `Time: ${nowIso}`,
  `Workflow: ${workflowName}`,
  `Workflow ID: ${wfId || 'N/A'}`,
  `Execution ID: ${executionId}`,
  `Error: ${errMessage}`,
  errStack ? `Stack: ${String(errStack).slice(0, 5000)}` : '',
].filter(Boolean).join('\n');

const upsertRes = await apiRequest.call(this, {
  method: 'POST',
  path: '/contacts/upsert',
  body: {
    locationId: cfg.locationId,
    email: cfg.recipientEmail,
    firstName: cfg.recipientFirstName,
    lastName: cfg.recipientLastName,
    name: `${cfg.recipientFirstName} ${cfg.recipientLastName}`,
  },
});
if (!upsertRes.ok) {
  throw new Error(`Error notifier failed on contact upsert: ${upsertRes.status} ${JSON.stringify(upsertRes.data)}`);
}

const contactId = upsertRes.data?.contact?.id || upsertRes.data?.id || upsertRes.data?.contactId;
if (!contactId) {
  throw new Error(`Error notifier cannot find contactId from upsert response: ${JSON.stringify(upsertRes.data)}`);
}

const sendRes = await apiRequest.call(this, {
  method: 'POST',
  path: '/conversations/messages',
  body: {
    contactId,
    type: 'Email',
    subject,
    message: bodyText,
    emailTo: cfg.recipientEmail,
  },
});
if (!sendRes.ok) {
  throw new Error(`Error notifier failed sending email: ${sendRes.status} ${JSON.stringify(sendRes.data)}`);
}

return [{
  json: {
    ok: true,
    notified: true,
    workflowId: wfId,
    executionId,
    contactId,
    subject,
  },
}];
